schema: fpga-design-agent/architecture/v1
design: ping_responder
top: ping_top
blocks:
  - {name: ping_top, function: "Top wiring: fpga_shell, clk_gen, reset_sync x2, phy_rst_seq, id window, ping datapath; no register logic of its own"}
  - {name: clk_gen, function: "MMCME2 turns CLK100MHZ into a 50 MHz eth clock (BUFG), and an ODDR drives the eth_refclk pin to the PHY"}
  - {name: reset_sync, function: "xpm_cdc_async_rst wrapper: asynchronous assert of cpu_resetn, synchronous release, one instance per clock domain"}
  - {name: phy_rst_seq, function: "Holds eth_rst_n low while reset is active, releases it PHY_RST_RELEASE_CYCLES clk cycles after reset release"}
  - {name: id_reg, function: "Read-only design ID register (design offset 0x00 = shell window address 0x80) returning DESIGN_ID"}
  - {name: rmii_rx, function: "RMII receiver in the 50 MHz domain: dibits to bytes on eth_crsdv, frame start and end, eth_rxerr, length limit"}
  - {name: frame_check, function: "Captures header fields and accumulates IPv4 and ICMP one's-complement sums while bytes arrive; CRC-32 FCS check at frame end"}
  - {name: frame_buf, function: "One RAMB36 (2 KB x 8) holding the received frame; written by rmii_rx, read by rmii_tx; single clock, no reset"}
  - {name: responder, function: "Accept/discard decision (EtherType, IPv4 version, fragment, destination, checksums, ICMP type 8), ARP reply decision, reply checksum values"}
  - {name: rmii_tx, function: "Builds the reply stream from frame_buf with field substitution, adds preamble, SFD, zero padding and CRC-32 FCS, serialises dibits to eth_txd"}
  - {name: led_pulse, function: "Sets led on the first eth clock of a reply, clears it after LED_PULSE_CYCLES/2 eth clocks (= LED_PULSE_CYCLES clk), restarts on each reply"}
  - {name: fpga_shell, function: "Reused test shell (shell/rtl/fpga_shell.sv): USB-UART register window, DESIGN_ID PING"}
interfaces:
  - {name: host_uart, between: [host_pc, fpga_shell], protocol: uart, prefix: uart_, module: fpga_shell}
  - {name: eth_rmii, between: [ethernet_phy, ping_top], protocol: other, prefix: eth_, module: ping_top}
  - {name: id_window, between: [fpga_shell, id_reg], protocol: simple, prefix: win_, module: id_reg}
  - {name: led_out, between: [ping_top, led_pulse], protocol: gpio, prefix: led, module: led_pulse}
clock_domains:
  - {name: clk, clock: clk, freq_mhz: 100}
  - {name: eth_refclk, clock: eth_refclk, freq_mhz: 50}
reset:
  synchronisers: [reset_sync]
crossings:
  - {from: async, to: clk, signal: rst_clk, primitive: xpm_cdc_async_rst, inline_in: reset_sync}
  - {from: async, to: eth_refclk, signal: rst_eth, primitive: xpm_cdc_async_rst, inline_in: reset_sync}
predicted_resources:
  lut: [400, 1500]
  ff: [300, 1200]
  bram_tile: [1, 2]
  dsp: [0, 1]

## design.xdc: pins and I/O standards from the board's master XDC (via board_constraints).
## Timing lines below are the I/O constraints for each port group.

## Pins and I/O standards (generated by board_constraints; do not edit pin numbers)
set_property -dict { PACKAGE_PIN E3   IOSTANDARD LVCMOS33 } [get_ports { clk }];  # CLK100MHZ
create_clock -add -name sys_clk_pin -period 10.00 -waveform {0 5} [get_ports { clk }];
set_property -dict { PACKAGE_PIN C12  IOSTANDARD LVCMOS33 } [get_ports { cpu_resetn }];  # CPU_RESETN
set_property -dict { PACKAGE_PIN D9   IOSTANDARD LVCMOS33 } [get_ports { eth_crsdv }];  # ETH_CRSDV
set_property -dict { PACKAGE_PIN D5   IOSTANDARD LVCMOS33 } [get_ports { eth_refclk }];  # ETH_REFCLK
set_property -dict { PACKAGE_PIN B3   IOSTANDARD LVCMOS33 } [get_ports { eth_rst_n }];  # ETH_RSTN
set_property -dict { PACKAGE_PIN C11  IOSTANDARD LVCMOS33 } [get_ports { eth_rxd[0] }];  # ETH_RXD[0]
set_property -dict { PACKAGE_PIN D10  IOSTANDARD LVCMOS33 } [get_ports { eth_rxd[1] }];  # ETH_RXD[1]
set_property -dict { PACKAGE_PIN C10  IOSTANDARD LVCMOS33 } [get_ports { eth_rxerr }];  # ETH_RXERR
set_property -dict { PACKAGE_PIN A10  IOSTANDARD LVCMOS33 } [get_ports { eth_txd[0] }];  # ETH_TXD[0]
set_property -dict { PACKAGE_PIN A8   IOSTANDARD LVCMOS33 } [get_ports { eth_txd[1] }];  # ETH_TXD[1]
set_property -dict { PACKAGE_PIN B9   IOSTANDARD LVCMOS33 } [get_ports { eth_txen }];  # ETH_TXEN
set_property -dict { PACKAGE_PIN H17  IOSTANDARD LVCMOS33 } [get_ports { led }];  # LED[0]
set_property -dict { PACKAGE_PIN D4   IOSTANDARD LVCMOS33 } [get_ports { uart_rxd_out }];  # UART_RXD_OUT
set_property -dict { PACKAGE_PIN C4   IOSTANDARD LVCMOS33 } [get_ports { uart_txd_in }];  # UART_TXD_IN

## Virtual clock for the RMII PHY pins. The PHY samples and launches on eth_refclk
## (50 MHz, generated in the FPGA by the MMCM); the period is 20 ns.
create_clock -name eth_virt -period 20.00;

## RMII receive inputs (PHY -> FPGA): launched by the PHY on eth_refclk.
## Input delay window: min 1 ns, max 6 ns after the reference edge.
set_input_delay -clock eth_virt -max 6.00 [get_ports { eth_crsdv eth_rxerr eth_rxd[0] eth_rxd[1] }];
set_input_delay -clock eth_virt -min 1.00 [get_ports { eth_crsdv eth_rxerr eth_rxd[0] eth_rxd[1] }];

## RMII transmit outputs and PHY reset (FPGA -> PHY): captured by the PHY on eth_refclk.
## Output delay window: max 4 ns, min -1 ns.
set_output_delay -clock eth_virt -max 4.00 [get_ports { eth_txen eth_txd[0] eth_txd[1] eth_rst_n }];
set_output_delay -clock eth_virt -min -1.00 [get_ports { eth_txen eth_txd[0] eth_txd[1] eth_rst_n }];

## Forwarded reference clock output to the PHY: output delay relative to the virtual clock.
set_output_delay -clock eth_virt -max 2.00 [get_ports { eth_refclk }];
set_output_delay -clock eth_virt -min -2.00 [get_ports { eth_refclk }];

## CPU reset button (asynchronous to clk; synchronised inside reset_sync) and the
## USB-UART receive pin (asynchronous; synchronised inside fpga_shell): input delay on clk.
set_input_delay -clock sys_clk_pin -max 2.00 [get_ports { cpu_resetn uart_txd_in }];
set_input_delay -clock sys_clk_pin -min 0.00 [get_ports { cpu_resetn uart_txd_in }];

## User LED and USB-UART transmit pin (FPGA -> host): output delay on clk (no external capture timing).
set_output_delay -clock sys_clk_pin -max 5.00 [get_ports { led uart_rxd_out }];
set_output_delay -clock sys_clk_pin -min -1.00 [get_ports { led uart_rxd_out }];

## design.xdc: pins and I/O standards from the board's master XDC (via board_constraints).
## Timing lines below are the I/O constraints for each port group.

## Pins and I/O standards (generated by board_constraints; do not edit pin numbers)
set_property -dict { PACKAGE_PIN E3   IOSTANDARD LVCMOS33 } [get_ports { clk }];  # CLK100MHZ
create_clock -add -name sys_clk_pin -period 10.00 -waveform {0 5} [get_ports { clk }];
set_property -dict { PACKAGE_PIN C12  IOSTANDARD LVCMOS33 } [get_ports { cpu_resetn }];  # CPU_RESETN
set_property -dict { PACKAGE_PIN D9   IOSTANDARD LVCMOS33 } [get_ports { eth_crsdv }];  # ETH_CRSDV
set_property -dict { PACKAGE_PIN D5   IOSTANDARD LVCMOS33 } [get_ports { eth_refclk }];  # ETH_REFCLK
set_property -dict { PACKAGE_PIN B3   IOSTANDARD LVCMOS33 } [get_ports { eth_rst_n }];  # ETH_RSTN
set_property -dict { PACKAGE_PIN C11  IOSTANDARD LVCMOS33 } [get_ports { eth_rxd[0] }];  # ETH_RXD[0]
set_property -dict { PACKAGE_PIN D10  IOSTANDARD LVCMOS33 } [get_ports { eth_rxd[1] }];  # ETH_RXD[1]
set_property -dict { PACKAGE_PIN C10  IOSTANDARD LVCMOS33 } [get_ports { eth_rxerr }];  # ETH_RXERR
set_property -dict { PACKAGE_PIN A10  IOSTANDARD LVCMOS33 } [get_ports { eth_txd[0] }];  # ETH_TXD[0]
set_property -dict { PACKAGE_PIN A8   IOSTANDARD LVCMOS33 } [get_ports { eth_txd[1] }];  # ETH_TXD[1]
set_property -dict { PACKAGE_PIN B9   IOSTANDARD LVCMOS33 } [get_ports { eth_txen }];  # ETH_TXEN
set_property -dict { PACKAGE_PIN H17  IOSTANDARD LVCMOS33 } [get_ports { led }];  # LED[0]
set_property -dict { PACKAGE_PIN D4   IOSTANDARD LVCMOS33 } [get_ports { uart_rxd_out }];  # UART_RXD_OUT
set_property -dict { PACKAGE_PIN C4   IOSTANDARD LVCMOS33 } [get_ports { uart_txd_in }];  # UART_TXD_IN

## Virtual clock for the RMII PHY pins. The PHY launches and captures on the 50 MHz
## reference (eth_refclk, generated in the FPGA by the MMCM); period 20 ns.
create_clock -name eth_virt -period 20.00;

## RMII receive inputs (PHY -> FPGA), CRS_DV, RXD[1:0], RX_ER.
## max 10.0 ns = PHY clock-to-output tCO max (10 ns in the RMII budget) plus board trace skew (~0);
## min 1.5 ns = PHY tCO min (hold side). Data valid window is therefore 8.5 ns of the 20 ns period.
set_input_delay -clock eth_virt -max 10.00 [get_ports { eth_crsdv eth_rxerr eth_rxd[0] eth_rxd[1] }];
set_input_delay -clock eth_virt -min 1.50 [get_ports { eth_crsdv eth_rxerr eth_rxd[0] eth_rxd[1] }];

## RMII transmit outputs and PHY reset (FPGA -> PHY), TXEN, TXD[1:0], RSTN.
## max 4.5 ns = PHY setup requirement tSU (4 ns) plus trace skew (0.5 ns);
## min -1.5 ns = -(PHY hold requirement tH 2 ns) plus trace skew (0.5 ns).
set_output_delay -clock eth_virt -max 4.50 [get_ports { eth_txen eth_txd[0] eth_txd[1] eth_rst_n }];
set_output_delay -clock eth_virt -min -1.50 [get_ports { eth_txen eth_txd[0] eth_txd[1] eth_rst_n }];

## Forwarded 50 MHz reference to the PHY (ODDR output). Skew only: max 0.5 ns, min -0.5 ns
## (trace skew between the eth_refclk pin and the PHY data pins).
set_output_delay -clock eth_virt -max 0.50 [get_ports { eth_refclk }];
set_output_delay -clock eth_virt -min -0.50 [get_ports { eth_refclk }];

## CPU reset button and USB-UART receive pin: asynchronous to clk. Synchronised inside
## reset_sync and fpga_shell. Input delay 2 ns max (board skew and button edge allowance),
## min 0 ns (no hold relation to clk).
set_input_delay -clock sys_clk_pin -max 2.00 [get_ports { cpu_resetn uart_txd_in }];
set_input_delay -clock sys_clk_pin -min 0.00 [get_ports { cpu_resetn uart_txd_in }];

## User LED and USB-UART transmit pin (FPGA -> host): no timed external capture.
## Output delay 5 ns max (driver tCO plus trace allowance), -1 ns min (hold allowance).
set_output_delay -clock sys_clk_pin -max 5.00 [get_ports { led uart_rxd_out }];
set_output_delay -clock sys_clk_pin -min -1.00 [get_ports { led uart_rxd_out }];

