## design.xdc: pins and I/O standards from the board's master XDC (board_constraints).
## Do not edit pin numbers here.

set_property -dict { PACKAGE_PIN D4   IOSTANDARD LVCMOS33 } [get_ports { UART_RXD_OUT }];  # UART_RXD_OUT
set_property -dict { PACKAGE_PIN C4   IOSTANDARD LVCMOS33 } [get_ports { UART_TXD_IN }];  # UART_TXD_IN
set_property -dict { PACKAGE_PIN E3   IOSTANDARD LVCMOS33 } [get_ports { clk }];  # CLK100MHZ
create_clock -add -name sys_clk_pin -period 10.00 -waveform {0 5} [get_ports { clk }];
set_property -dict { PACKAGE_PIN C12  IOSTANDARD LVCMOS33 } [get_ports { cpu_resetn }];  # CPU_RESETN
set_property -dict { PACKAGE_PIN D9   IOSTANDARD LVCMOS33 } [get_ports { eth_crsdv }];  # ETH_CRSDV
set_property -dict { PACKAGE_PIN D5   IOSTANDARD LVCMOS33 } [get_ports { eth_refclk }];  # ETH_REFCLK
set_property -dict { PACKAGE_PIN B3   IOSTANDARD LVCMOS33 } [get_ports { eth_rst_n }];  # ETH_RSTN
set_property -dict { PACKAGE_PIN C11  IOSTANDARD LVCMOS33 } [get_ports { eth_rxd[0] }];  # ETH_RXD[0]
set_property -dict { PACKAGE_PIN D10  IOSTANDARD LVCMOS33 } [get_ports { eth_rxd[1] }];  # ETH_RXD[1]
set_property -dict { PACKAGE_PIN C10  IOSTANDARD LVCMOS33 } [get_ports { eth_rxerr }];  # ETH_RXERR
set_property -dict { PACKAGE_PIN A10  IOSTANDARD LVCMOS33 } [get_ports { eth_txd[0] }];  # ETH_TXD[0]
set_property -dict { PACKAGE_PIN A8   IOSTANDARD LVCMOS33 } [get_ports { eth_txd[1] }];  # ETH_TXD[1]
set_property -dict { PACKAGE_PIN B9   IOSTANDARD LVCMOS33 } [get_ports { eth_txen }];  # ETH_TXEN
set_property -dict { PACKAGE_PIN H17  IOSTANDARD LVCMOS33 } [get_ports { led }];  # LED[0]

## ---- I/O timing ----

# Virtual clock for the RMII interface: the 50 MHz reference (eth_refclk) is
# generated inside the FPGA by the MMCM from clk, so it has no input port to
# constrain. Its period is 20 ns. The RMII I/O delays are relative to this clock.
create_clock -name eth_vclk -period 20.000;

# RMII receive inputs (PHY drives them on the reference clock): carrier sense/
# data valid, receive error and receive data. Setup/hold window per the RMII
# timing budget: 4 ns before and 2 ns after the reference edge, with margin.
set_input_delay -clock eth_vclk -max 6.0 [get_ports { eth_crsdv eth_rxerr eth_rxd[*] }];
set_input_delay -clock eth_vclk -min 1.0 [get_ports { eth_crsdv eth_rxerr eth_rxd[*] }];

# RMII transmit outputs (FPGA drives them, PHY samples on the reference clock):
# the PHY needs 4 ns setup and 2 ns hold around the reference edge.
set_output_delay -clock eth_vclk -max 4.0 [get_ports { eth_txen eth_txd[*] }];
set_output_delay -clock eth_vclk -min -2.0 [get_ports { eth_txen eth_txd[*] }];

# The reference clock pin is a forwarded clock (ODDR from the MMCM output):
# its output delay is set so the edge lands at the PHY with its skew budget.
set_output_delay -clock eth_vclk -max 1.0 [get_ports { eth_refclk }];
set_output_delay -clock eth_vclk -min -1.0 [get_ports { eth_refclk }];

# Reset input from the CPU button: asynchronous to clk, synchronised inside
# (xpm_cdc_async_rst). Constrained as a clk-relative input for the report.
set_input_delay -clock sys_clk_pin -max 2.0 [get_ports { cpu_resetn }];
set_input_delay -clock sys_clk_pin -min 0.0 [get_ports { cpu_resetn }];

# UART receive pin from the host: asynchronous, synchronised by fpga_shell.
set_input_delay -clock sys_clk_pin -max 2.0 [get_ports { UART_TXD_IN }];
set_input_delay -clock sys_clk_pin -min 0.0 [get_ports { UART_TXD_IN }];

# UART transmit pin to the host and the user LED: slow human-facing outputs,
# constrained against clk with a 2 ns budget.
set_output_delay -clock sys_clk_pin -max 2.0 [get_ports { UART_RXD_OUT led }];
set_output_delay -clock sys_clk_pin -min 0.0 [get_ports { UART_RXD_OUT led }];

# PHY reset output: held low for 1000 clk cycles after power-up, so the timing
# is a static level; constrained against clk with a 2 ns budget.
set_output_delay -clock sys_clk_pin -max 2.0 [get_ports { eth_rst_n }];
set_output_delay -clock sys_clk_pin -min 0.0 [get_ports { eth_rst_n }];
